INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h1>Идоракунии зараранок ва бемориҳои киноа дар системаи обёривии қатқатӣ: Раҳнамаи мукаммал ва ихтисосӣ</h1>\n\n<h2>Муқаддима: Лозимияти мувофиқсозии обёривии қатқатӣ бо саломатии расти киноа</h2>\n<p>Киноа (<em>Chenopodium quinoa</em>) аз сабаби муқовимати баҳорушанд ба стрессҳои шӯрнокӣ ва хушкӣ, яке аз интихоботи асосӣ барои кбудани минтақаҳои нимхушк ва шӯр аст. Аммо киноа растииест, ки дар давраҳои ҳассоси афзоиш, ба намноки мувозинатпазир ва мунтазам дар хок ниёз дорад. Яке аз мушкилоти маъмул дар парвариши киноа паҳншудани зуд бемориҳои зангукӣ ва зарари баргҳо аз ҷониби зараранокҳои ҳайвонот аст, ки одатан бо зиёдшудани намнокии нисбӣ ва наммондани мӯндамоти хок барои давраи тӯлонӣ вобастагии бевосита дорад. Истифодаи <strong>обёривии қатқатӣ</strong> ва <strong>наварии тейп</strong> (Drip Tape) метавонад ҳамчун чораи дифоъии самаранок амал кунад, зеро ин системаҳо намнокӣ-ро на дар тамоми майдони кишт, балки танҳо дар минтақаи маҳдуд атрофи решаҳо (Root Zone) марказӣ мекунанд ва аз наммондану мӯндамоти сатҳ ва баргҳо пешгирӣ мекунанд. Ин роҳ, ҳадди бемориҳои пуфакпӯш (Powdery Mildew) ва зангзанг (Rust)-ро ба таври наздик зиёд мекунад ва муқовимати растииро дар баробари ҳамлаҳои зараранок боло мебарад. Инчунин, нигоҳдории намнокӣ аз сатҳи хок дур, монеаи ҷазби зараранокҳои ҳашарот мебошад, ки одатан барои андехтани тухмҳо ба намнокии сатҳӣ ниёз доранд. Ин механизми дифоъӣ, асоси қавӣ барои идоракунии ягонаи зараранокҳо ва бемориҳо дар майдонҳои киноа месозад.</p>\n\n<h2>Нақши овардани анъанаҳои обёркунӣ дар идоракунии бемориҳои қирчагӣ</h2>\n<p>Дар обёркунии анъанавии боронӣ, қатраҳои об масолеҳи шустарони (масехи) корро иҷро мекунанд ва спораҳои қирчаги зери решаи хокро ба сӯи боло ва баргҳои поёнтар паҳн мекунанд. Ин шартҳо моҳити идеалӣ барои афзоиши зудии қирчагҳо эҷод менамояд. Дар навбат, истифодаи системаи қатрагӣ (сачкаӣ) тақсимоти якхелаи намӣ дар масофаҳои кӯтоҳ ва идорашавандаро мушкил мекунад ва эҳтимоли ташкили туман дар қабатҳои поёни таҷи (кӯпо)и растаниро ба ҳадди ақал мерасонад. Барои таҳқиқи дақиқтари робита байни zichadagi (ғализии) ғунумошӣ ва хатари беморӣ, мавзӯъ <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%A8%D8%A7%D9%85%DB%8C%D9%87-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Ҳаҷми бубӯл барои беморӣ дар гектар</a> меонад, ки нисбат ба шиддати зиёдани растаниҳо ва эҳтимоли афзоиши бемориҳои байни сабуни мебарояд. Дар гуномошҳои сахт (ғалӣ), ҳаво дар дохили таҷии растанӣ камтар ҳаракат мекунад ва намӣ бештар дар хок боқӣ мемонад, ки шартҳоро барои омилҳои қирчагиимонанд <em>Pseudomonas</em> ва <em>Uromyces</em> муяссартар мекунад. Ғайр аз ин, идоракунии дақиқи ҳаҷми оби воридшуда бо бичоқии навъии сачкаӣ аз хунҷуни решаҳо ба далели нафаромидашуда будани хок ва зареши нокофӣ пешгирӣ мекунад ва монеаи боздории пайдоиши ранги қабъаи бафтҳои решагӣ аст. Ин раванд саломатии системаи решагиро ҳамоҳанг мекунад, ки ниме аз қудрати муҳориботарини растанӣ бар зидди омилҳои беморихез мебошад.</p>\n<ul>\n<li><strong>Афзоиши суръати бухоршавии ҷойи ғунумошӣ:</strong> Бо партониши маҳдуди об дар ҷойи чанде, сатҳи хок зудтар хушк мешавад ва боздошти пайдоиши муҳити нокофӣ барои қирчагҳои хокӣ мекунад.</li>\n<li><strong>Идоракунии шӯрӣ ва кам кардани стресс:</strong> Киноа яки ресидӯрангист, аммо шустушӯи шӯрӣ метавонад сабаби зиёдшавии ҳассосият ба паразитони афлатида бошад. Шустушӯи шӯрӣ бо риштаи наққорӣ мадори вақтро беҳтар мекунад ва <a href="https://navar-abyari.ir/fawaid-nawwar-riyy-atip/">Фоидаҳои риштаи наққорӣ</a> ро дар шустушӯи хок муайян мекунад. Ин назорати дақиқ стресси физиологироки ресидоҳоро кам мекунад ва муқовимати умумии онро баланд мебарад.</li>\n</ul>\n\n<h2>Идоракунии паразитони ҳайвонот бо истифода аз риштаи наққорӣ ва қатраандозӣ</h2>\n<p>Паразитони ҳайвонот, ба монанди афлатони ардо (Aphids), кӯрпул (Mites) ва ширинпӯстон (Thrips), одатан аз беҳҳои поёнӣ ва баргҳои поёнии ресидӯрангистаро иваз мекунанд. Системаи оғоз қатраандозӣ, бо нигоҳ доштани хушкии бини ресидӯрангистаро, даврони зиндагии ин паразитонро беҳ куз мекунад ва паноҳгоҳи мувофиқи онҳоро аз байн мебарад. Инчунин, кам шудани хатари коғазҳо ба маънои кам кардани миқдори доруи химикӣ аст ва зистшури ҳасилзедӣ ба таври хос нигоҳ дошта мешавад, ки душманони табиии паразитон нақши самараноктарро дар назорати шумораи онҳо иҷро намоянд. Дар заминагони, ки аз обҳои сифатнок истифода мекунанд, риштаи наққорӣ <a href="https://navar-abyari.ir/samak-jidar-sharit-al-ray/">Симмашъи ҷадид риштаи ришта</a> метавонад аз ҷанб шудани моддаҳои майда ва пӯсишдани шурворагӣ пешгирӣ кунад; зеро пӯсиши ин шурворагӣ шиддати обии маҳаллӣ эҷод мекунад, ки ресидоҳоро ба ҳамлаи сӯсоқҳои баргхӯр аст. Ин шиддатҳои маҳаллӣ нуқтаҳои заифро эҷод мекунанд, ки паразитон онҳоро муайян мекунанд ва ғазииро оғоз мекунанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-کینوا-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های کینوا با آبیاری قطره‌ای - تصویر 1"/><figcaption>аштуборҳо ва бемориҳои ҳосил, ороениеи қатрагӣ, кинва</figcaption></figure>\n\n\n<h2>Хатогиҳои оддӣ дар насби системаи қатрагӣ ва таъсири он ба кинва</h2>\n<p>Дар тарҳрезии техникӣ системаи қатрагӣ, хатогиҳо ҳангоми насб метавонанд ба бемориҳои растаниҳо ва zarar ба решаҳо оварда расонанд. Насби нодурусти қатрагиронҳо дар роҳе, ки бевосита об ба дарахти равона мекунад, хавфи бемориҳои бактериявӣ ва зарарҳои <em>Bacterial Blight</em> ро баланд мебардорад. Бинобар ин, истифодаи қатрагиронҳо бо кунҷи хуруҷи мувофиқ ё пайвасткунандагоне ба монанди <a href="https://navar-abyari.ir/loe-nakhi-90-irrigation-guide/">ло 90 дараҷа</a> барои идоракунии парфӯни уфуқӣ ба идоракунии беҳтари роҳи об ва пешгирӣ аз часидани баҳоришӣ ба пути растани кӯмак мекунад. Инчунин, баррасии вақти ороение нақши ҳалкунанда дорад; ороение дар соатҳои оғози субҳ ба решаҳои васеътар дастрасӣ мебахшад, дар ҳоле ки ороение шабе ба вуҷуди баҳориши бооддӯр ва пинҳон оварда мерасонад ва шароити афзоиши қарчашоӣ-қамароро қавӣ мекунад. Ин баррасӣ бояд бо суръати бухоршавии маҳаллӣ мувофиқ бошад, то ки заминаи хок имконияти барқарор шудан аз баҳориши иловагиро наоярад.</p>\n\n<h2>Масъалаҳои истилоҳи намакӣ, pH ва идоракунии шустан бо нақрагирӣ</h2>\n<p>Доимии кинва дар муқобила бо намакӣ ба вазъияти 6 то 8.5 дараҷаи pH-и хок маҳдуд аст; баромадан аз ин вазъият ҷидофи унсурҳои хурд, ба монанди оҳан ва рӯйро вайрон мекунад ва растаниро аз нуқтаи назари ранг ва сифат заиф мекунад ва рақобати онро дар муқобила бо сурбукҳо ва ҳашаротҳо баланд мебардорад. Истифодаи нақрагирӣ бо сӯроҳкуниҳои хурдтар имконияти шустани мубод ва дақиқтари намакиро фароҳам меорад. Дар системаҳои ороениеи зери рӯи замин, ки баъзан дар минтақаҳои хушк ба ҷои нақрагирӣ истифода мешавад, идоракунии намак ҳассоси аст; зеро дар ин усул, шустани намак душвортар мешавад ва бояд диққати бештарро ба ҳисобкунии дебит воридотӣ ва шустаниш татбиқ кард. Ин ҳассосиҳо талаботи назорати доимии намакиро дорад, то аз ҷамъшавии намкҳои зараровар дар минтақаи реша пешгирӣ шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-کینوا-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های کینوا با آبیاری قطره‌ای - تصویر 2"/><figcaption>ҳашароти ҳосил, беморӣҳо, обёрӣи қатқомавӣ, қиноа</figcaption></figure>\n\n\n<h2>Саволҳои оммавӣ (FAQ)</h2>\n<h3>Оё обёрӣи қатқомавӣ худ ба худ ҳашароти растенияро аз мисм мекунад?</h3>\n<p>Не, обёрӣи қатқомавӣ усули пешгирокунанда ва муҳофизаткунанда аст ва мустақиман ҳашаротро аз мисм намекунад. Аммо тавассути эҷоди шароити ногуна барои қаламчин ва ҳашароти хокӣ, ҳаҷи ниёз ба пестсидагии кимиёвиро ба таври назаррас кам мекунад. Ин камшавии пестсидагӣ хароҷотҳои истеҳсолотро кам карда ва саломатии муҳити майдони деҳотро беҳтар мекунад.</p>\n<h3>Фосилаи муносиби наҳорӣи об дар қиноа чӣ қадар аст?</h3>\n<p>Дар фосилаи стандартии кӯрпартоии 40 то 50 сантиметр, фосилаи 15 то 20 сантиметр аз маркази қатори кӯрпартоӣ то наҳорӣи об тавсия дода мешавад. Ин фосила бояд бо асосҳои умумии тақсимоти намнокӣ дар майдонҳои монанд танзим шавад; барои маълумоти бештар, шумо метавонед дастораи ҷамъи партобидани қиёбо бо усули обёрӣро хонед. Асосҳои физикии тақсимоти намнокӣ дар ин ду ҳосил монанд аст ва метавонад намуна барои танзими дақиқ дар қиноа бошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-کینوا-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های کینوا با آبیاری قطره‌ای - تصویر 3"/><figcaption>ҳашароти ҳосил, беморӣҳо, обёрӣи қатқомавӣ, қиноа</figcaption></figure>\n\n\n<h3>Оё имкони тағзиқи маҳлуқ (фургисатсион) бо наҳорӣи об вуҷуд дорад?</h3>\n<p>Бале, системаи риллӣ бар системҳои фитигатсион мувофиқ аст. Бо парроҳ кардани қобори мувозинатнок, ғизои ошкор шуда, муқовимат ба мушкилоти муҳити зист ва ҳуҷуми зараррасонҳо зиёд мешавад. Барои пешгирии пӯшидани созишҳои нори риллӣ бо оқилоби қобор, ба монанди <a href="https://navar-abyari.ir/pepper-drip-tape-irrigation-guide/">кабчаи қарҳор дар обории риллӣ</a> тасвиш мешавад. Ин филтратсияи дақиқ, ягонагии системаи обориро нигоҳ медорад ва аз пайдоиши бемориҳо аз сабаби мушкилоти ғизоӣ пешгирӣ мекунад.</p>\n\n<h2>Хулоса ва тавсияи ниҳоӣ барои деҳқонон</h2>\n<p>Интихоби кинуа ҳамчун маҳсулот дар минатоқи хушк ва шӯр, қарори оқилона аст; дар шароите, ки системаи обори аз ҷиҳати техникӣ ва вақтӣ созмон дода шавад. Зараррасонҳо ва бемориҳои кинуа бо иҷрои софтаринаҳои обори бодаракӣ пешгирӣ ва назорат мекунанда. Бо нигоҳ доштани хуши сатҳи тукни ошкор, кам кардани хатари пайдоиши зангуҳо ва беҳтар кардани тақсимоти шӯр тавассути риллӣ, метавон ба маҳсулоти бо сифати баланд ва хароҷоти камтари кимиёвӣ ноил шуд. Деҳқонони камтаҷриба дар риллӣ, метавонанд бо таҳқиқ <a href="https://navar-abyari.ir/potato-drip-tape-irrigation-guide-iraq/">моҳаркаи обории риллӣ чирей</a> бо принсипҳои монанди назорати намнокӣ ва шӯр ошно шаванд. Дар анҷом, назорати доимии боғҳо ва мутобиқ кардани даври обори бо иқлими маҳаллӣ, калиди асосӣ барои парвариши солим ва устувори кинуа мешавад. Ин равиши умумӣ, хатари иқтисодӣ ва биологииро ба ҳадди ақал мерасонад.</p>\n','Идоракунии мукаммали зарароварон ва бемориҳои кинуа дар системаҳои оборӣи қатрагӣ ва назорати NPK: Раҳнамои махсусӣ','Дар ин дастурномаи мукассас, мо баррасӣ мекунем, ки истифодаи системаҳои обварии қатрагӣ ва риштагӣ чӣ гуна муҳити зистии майдони кinoa-ро тавре тағйир медиҳад, ки хатари биморӣҳои куфакмонӣ, ба монанди пудр ва занг, кам шудан ва миқдори зараррасони аҷоӣ, ба монанди моҳрӯйҳои нарм, идора шудан мешавад. Мо баррасии тафсилотҳои техникӣ, аз ҷумла масофаи мувофиқи риштагӣ, барномаи обварӣ, идоракунии намакӣ ва pH-и хок, ва инчунин усулҳои шӯстани намакҳо бо риштагӣ-ро иҷро мекунем. Мақсади ин мақола, пешниҳоди як чорчӯбаи амалӣ барои деҳқонӣст, то бе илтифоти зиёд ба моддаҳои кимиёвӣ, солим будани шоха ва решаи растаниро нигоҳ дошта, самаранокии ниҳоии маҳсулотро беҳтар кунанд. Бо таваҷҷӯҳ ба принсипҳои илмӣ ва таҷрибаҳои дар майдон, мо нишон медиҳем, ки системаи обварии тарҳӣ-шудаи дақиқ, саҳбати дифоии аввал бар муқобили биморӣҳои физиологӣ ва биологӣ мебошад. Ин мақола бо шарҳи механизмҳои физиологикавии растании кinoa дар зидди шиддатҳои муҳитӣ ва пешниҳоди ҳаллиҳои беҳтар, қадаме муҳим дар кишоварии падовав ва иқтисодии кinoa дар минтақаҳои хушк ва намакдӯст мебошад.','publish','closed','closed','idorokunii-mukammali-zararavaron-kinua-sistema-oborii-qatragi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
