INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррада оид ба аҳамияти обидори гандуи ҷигарӣ бо лентҳои нӯкӣ</h2>\n<p>Ҷигари ганду (сорго) як намуди ғаллаи бисёрҷанба аст, ки на танҳо ҳамчун ғизои ҳайвонот, балки ба сабаби сифати баланди протсеин ва муқоимат ба шароити мураккаби иқлимӣ дар кишоварзии Эрон ва ҷаҳон ҷои махсус дошт. Гарчанде ин гиёҳ нисбат ба фишори хушкӣ тобори баландеро нишон медиҳад, аммо дар марҳалаҳои ҳисоби инкишоф, идоракунии дақиқи обрасонӣ меваедаро байни ҳосили миёна ва ҳосили аъло муайян менамояд. Системаҳои обидори қатраӣ, хусусан лентаҳои нӯкӣ бо таблагҳо (палак), усули самаранок барои расонидани об ба минтақаи решаҳо бе инкишофи қавии буғоб аст.</p>\n<p>Истифодаи лентаҳои нӯкӣ барои ҷигари ганду на танҳо ба таҳфизоти сарфи об, балки ба беҳтар кардани тақсимоти робитаҳои решаӣ ва зиёд шудани ҷидобкунии моддаҳои ғизоӣ кӯмаки зиёнеро мерасонад. Аммо калиди муваффақият дар ин система дар «нигоҳдории» он мебошад. Ноодогоҳӣ аз принсипҳои дурусти нигоҳдорӣ метавонад боиси бехӯбиди қатраандозҳо, норасониҳои вазнин ва кам шудани ҳосилнокӣ гардад.</p>\n\n\n\n<h2>Шарҳи техникӣ системаи обидори қатраӣ дар бӯғи ҷигари ганду</h2>\n<p>Дарки коркарди техникӣи лентаҳои нӯкӣ барои деҳқонон зарур аст. Ин лентаҳо аз қатраандозҳое иборатанд, ки бо фосилаҳои муайян бар як лӯлаи камерагӣ ҷойгир шудаанд. Ҳар як қатраандоз бо фишор ва суръати доимӣ, миқдори муаййан обро ба дохили хок мерезад. Дар ҷонири ҷигари ганду, ки одатан бо таври намуворӣ (худҳашӣ) анҷом меёбад, лентаҳои нӯкӣ дақиқан дар дарозии фосилаи байни сатҳҳо (қаторҳо) ё зер ба тоҷуқ ҷойгир мегарданд, то решаҳо дастрасӣи мустақим ба намӣ дошта бошанд.</p>\n<h3>Параметрҳои асосӣ дар интихоби система</h3>\n<p>Барои ҳосили беҳтар, интихоби нӯри (назар) коҳишкунанда бо рафтори дуруст муҳим аст. Рафтори мӯътодо одатан дар ҳаҷми 4 то 8 литр дар соат барои аксари заминҳо истифода мешавад. Инчунин, масофаи нӯри коҳишкунандаҳо аз ҳам (spacing) бояд вобаста ба намуди хок ва иқлими минтақа танзим карда шавад. Агар шумо бинед, дониши худро дар бораи системаҳои гуногун васеъ кунед, таҳқиқoti намудҳои системаҳои оборӣ метавонад ба шумо дидҷаи комилтар бахшад. Ба назар гиред, ки сифати худи навар мустақиман ба умри система таъсир мерасонад; бинобар ин, истифодаи маводи мутобиқ бо стандартҳои байналмилалӣ зарур аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-ارزن-با-نوار-تیپ-نکات-کلیدی-تصویر-شاخص.webp" alt="نگهداری ارزن با نوار تیپ: نکات کلیدی - تصویر 1"/><figcaption>нигоҳубини навари коҳишкунандаи фасил будубоми арза, парвариш</figcaption></figure>\n\n<h2>барномаи вақтӣ ва профили рушди арза</h2>\n<p>арза решаи наботии дар марҳилаҳои гуногуни рушд ба миқдори гуногуни об ниёз дорад. Давраи рушди он одатан марҳилаҳои шукуфтан, рушди решаҳо, гулдонӣ ва ҳосилгирӣро дар бар мегирад. Дар навари коҳишкунанда мо "профили ободнокӣ"-ро дорем, ки ин марҳилаҳоро мутавозеъ мекунад.</p>\n<ul>\n<li><strong>Марҳилаи шукуфтан:</strong> Ниёз ба оби миёна то баланд. Мақсад, тез ба кор доштани решаҳои арзист.</li>\n<li><strong>Марҳилаи вобастагии решаҳо:</strong> Ҳассосият ба таъсири хушкӣ зиёд мешавад. Ободнокӣ бо нави коҳишкунанда дар ин марҳила бештар ба баландии арза ва зичии гулдон таъсир мерасонад.</li>\n<li><strong>Марҳаи гулшакунӣ ва дучоҳишӣ:</strong> Тоҷҷарби обӣ дар сурати пуршавии дучаҳиҳо барои андозаи дучаҳиҳо ба таври ҷиддӣ коҳиш меовард.</li>\n</ul>\n<p>Оҳангкунии обкунӣ бо нақши релови, маънои онро надорад, ки система доимо кор мекунад. Бале, вале вазъияти дақиқ бояд асоси маълумоти тенометри ё қобилияти обии хок суръат бошад. Ин дақиқӣ талаб мекунад, ки нақшҳо суръати якхела доранд; дар бораи <a href="https://navar-abyari.ir/fawaid-nawwar-riyy-atip/">Фоаидҳои нақши релови тип</a> ва чӣ тавр он ба якхелагии ҷунбӯл таъсир мерасонад, метавонед боз пурсидед.</p>\n\n\n\n<h2>Нуқтаҳои асосӣ ва амалӣ нигоҳдории нақши релови дар майдони арҷарзан</h2>\n<p>Нигоҳдории система, мувозинати байни се унсур «манбаи об», «хати асосӣ» ва «нақш» мебошад. Дар ин ҷо чораҳои асосиро баррасӣ мекунем:</p>\n<ol>\n<li><strong>Филтрасияи пешрафта:</strong> Оби бӯд бояд мушки ва чанг надорад. Фильтрҳои таракор (Screen) ё disku бо тормоли мувофик, нахустин хатти муқоимат ба хастагии каппучиҳо мебошад. Филтрро ҳар 10 то 14 рӯз як бор санҷиш ва шӯстанед.</li>\n<li><strong>Қуридон (Curing) пас аз ҳар давраи обёрӣ:</strong> Пас аз хатми ҳар ҷаласаи обёрӣ, фишори системаҳоро бо оҳистӣ озод накунед. Иҷозат диҳед, ки об дар нӯр партофта шавад, то намӣ дар минтақаи реша нигоҳ дошта шавад ва аз ҷамъшавии нӯр ба сабаби холии ҳаво пешгирӣ карда шавад.</li>\n<li><strong>Санҷиши биннии нӯрҳо:</strong> Дар ҳар давраи обёрӣ, камтарин 10% нӯрҳоро ба таври тасодуфӣ боз назорат кунед. Ишораҳои беназоимӣ ба монанди «хаткашидан» тавассути ҳайвонот, паре шудан аз сабаби ҳашорот, ё ҷамъшавии (булбоншавӣ) нӯр бояд фавран сабт ва ислоҳ карда шаванд.</li>\n<li><strong>Идоракунии чорвоҳои даштӣ:</strong> Чорвоҳои даштӣ метавонанд ба нӯр тиби зарари физикӣ зананд ё бидоҳад, ки нӯр аз роҳаш берун шавад. Аз чоркунии амиқ дар масофае, ки нӯр ҷойгир аст, гузаред. Агар нӯр дар хок бошад, аз чоркунии амиқтар аз амиқии нӯр худдорӣ кунед.</li>\n</ol>\n<h3>Идоракунии фишор ва помпа</h3>\n<p>Фишори мувофиқ дар вуруд ба навор бояд доимӣ бошад. Рафтогарии фишор боиси ифлосии қатрапоён мегардад. Истифодаи регуляторҳои фишор (PRV) дар оғози ҳар хати паҳлӯвӣ ба кафолат ҳосилшавии якхелагии андозаи баромади об, ҳатто дар қисми ниёзбади замин кӯмак мекунад. Барои кафолати он, ки фишори лозима доред, омӯдани роҳи интихоби навори ирригатсияи қатраии мувофиқро вобаста ба шароити топографии заминро тавсия мекунем.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-ارزن-با-نوار-تیپ-نکات-کلیدی-کاربرد-عملی.webp" alt="نگهداری ارزن با نوار تیپ: نکات کلیدی - تصویر 2"/><figcaption>crop drip tape maintenance care арзун</figcaption></figure>\n\n<h2>Ҷадвали муқоисавии шароити нигоҳдорӣ: хатои оддӣ ба ҳалли масъала</h2>\n<table>\n<thead>\n<tr>\n<th>Мушкилот/Хатои оддӣ</th>\n<th>Сабаби эҳтимолӣ</th>\n<th>Ҳалли масъала ва чораи фаврӣ</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Ифлосии қатрапоён</td>\n<td>Фильтрацияи заиф ё отлақи минералӣ дар об</td>\n<td>Иловаи филтр, шустани система бо кислоти заиф, тозакунии тофтаҳо</td>\n</tr>\n<tr>\n<td>Кам шудани якхонагии омади об дар охирин шинаси</td>\n<td>Паст шудани фишор аз сабаби дағаллудаи баланди боғзор ё ҳарорати паст</td>\n<td>Афзудани шиддати омади об, тақсимоти хатҳои паҳлӯгӣ, истифодабарии регулятори фишор</td>\n</tr>\n<tr>\n<td>Паредани шинас аз ҷониб ҳайвонот</td>\n<td>Ғусфанд кардан аз ҷониб сӯғун, пастьёка ё ёранг</td>\n<td>Истифодабарии шинасҳои зидди газ, пӯшидани дарҳо, назорати мунтазам</td>\n</tr>\n<tr>\n<td>Печистан ва гарданхӯрда шудани шинас</td>\n<td>Кушода будан навор ҳангоми ҷамъ кардан ё таъмири нодиққонат</td>\n<td>Пӯшидан шинари барори ҳангоми ҷамъ кардан, шур будан навор, истифодаи пастакҳои нигоҳдоранда</td>\n</tr>\n<tr>\n<td>Фасоли микробиологӣ (бактерияҳо)</td>\n<td>Боқӣ мондани намнокӣ дар навор дар мавсими сард</td>\n<td>Истифодаи дезинфексикунандаҳои ҷойдошт пеш аз мавсим, холӣ кардани пурраи навор дар охир мавсим</td>\n</tr>\n</tbody>\n</table>\n\n\n\n<h2>Ҷавоб ба саволҳои маъмул (FAQ)</h2>\n<h3>Оё навори дароз (типа) барои гандум дар хокҳои вазнин самаранок аст?</h3>\n<p>Бале, аммо бо эҳтиёти махсус. Дар хокҳои вазнин (глоистӣ), ҷузъи об сусттар аст. Бинобар ин, беҳтар аст, ки аз қатраконҳо бо дараҷаи баландтар ва масофаи камтар истифода варзед, то намнокӣ ба чуқурҳавои решаҳо расад ва сатҳи хок пурра нашуда, ба афзоиши решаҳо монеъ гардад. Инчунин дар ин хокҳо, хуруфи тамаддури физикӣ баландтар аст, бинобар ин филтрасияи дугона тавсия мегардад.</p>\n<h3>Оё нӯрипӣ-лентаро дар солҳои пайдарпай бо арза метавон истифода бурд?</h3>\n<p>Ба сифати нӯрипӣ-лента вобаста аст. Нӯрипӣ-лентҳои стандартӣ одатан барои як мавсими (6 то 8 моҳ дар офтоб) сохта шудаанд. Агар нӯрипӣ-лента зери хок монда бошад (нӯрипӣ-лентаи зеризаминӣ), умри он метавонад то 3 то 5 сол зиёд шавад. Дар ин ҳолат, решаҳои арза дар паҳлуҳои нӯрипӣ-лента меҳамайд, бинобар ин нигорӣ дар бораи устувории ҷойгиршавии нӯрипӣ-лента муҳим аст. Барои маълумоти бештар дар бораи зичии ғалҷамъоварӣ, ки бояд бо фосила байни нӯрипӣ-лентҳо мувофиқ бошад, ба ҷадвал <a href="https://navar-abyari.ir/triticale-seed-per-hectare-density-table/">Зичии ғалҷамъоварии тритикал дар гектар</a> омед (гарчанде ки арза ва тритикал фарқ карда, принсипҳои муайян кардани зичӣ монанданд).</p>\n<h3>Вақти беҳтарин барои тоза кардани системаи нӯрипӣ-лента чист?</h3>\n<p>Вақти беҳтарин охири мавсими ҳосилзории арза аст, яъне вақте ки ҳашарот хушк шуда ё ғалҷамъоварӣ шудааст. Дар ин ҳолат, тоза кардан бо мӯҳримкунанда ё кислот, бе зарба расондан ба решаҳо, боиси тоза кардани пурраи роҳи ҷараён аз намакҳои асоснок ва биофильмаҳо мегардад. Пас система бо оби хунук шустушӯ карда шуда, барои мавсими оянда омода мегардад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-ارزن-با-نوار-تیپ-نکات-کلیدی-جزئیات-فنی.webp" alt="نگهداری ارزن با نوار تیپ: نکات کلیدی - تصویر 3"/><figcaption>crop drip tape maintenance care арза</figcaption></figure>\n\n<h2>Хулоса: Калиди устуворӣ дар боғи арза</h2>\n<p>Дароми на арз бо лавбазари рибони, раванди идомадор аст, намо дар як маротиба. Ин система гарчанде сармоягузории аввалина дорад, аммо бо назардошти андозаҳои баланди об ва энергия дар оросиши сатҳӣ, аз ҷиҳати иқтисодӣ ғолиб мебошад. Муваффақияти шумо ба се омили сарҳисса вобаста аст: аввалан, интихоби рибон бо суръати отрез ва масофаи мувофиқ барои парҳези арз; дуюм, идоракунии дақиқи сарчашмаи об бо филтрасияи қавӣ; ва сеюм, интизод дар парҳезҳои рутинӣ, ба монанди санҷиши босирӣ ва кюрир.</p>\n<p>Бо риояи асосҳои дар ин мақола зикршуда, шумо метавонед таъмин гардед, ки ҳар қатро оби ба ҷои бухор шудан, бевосита ба ҳадди дони арз илова меёбад. Диққати ба тафсилот чунин мисли меҳнатӣ замин, маводи хок ва намуди қатраандоз, фарқияти байни як системаи корӣ ва як системаи шодобро эҷод мекунад. Барои таъмини интихоби дурусти материал, ҳамеша ба манбаи дастрас муроҷиат кунед. Шумо метавонед дар бораи қиммати даврии Лӣ Флет ва дигар маводи оросишӣ аз манбаҳои ихтисосӣ маълумот гиред, то беҳтарин қарорро барои боғи худ гиред.</p>\n<p><strong>Маводҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%D9%82%DB%8C%D9%85%D8%AA-%D9%84%D9%88%D9%84%D9%87-%D9%84%DB%8C-%D9%81%D9%84%D8%AA/">D982DB8CD985D8AA D984D988D984D987 D984DB8C D981D984D8AA</a>, <a href="https://navar-abyari.ir/%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d9%be%d9%84%d8%a7%da%a9%d8%af%d8%a7%d8%b1/">Лавбазари рибонӣ бо паноми</a></p>','Нигоҳубinii zira\'i baxtashu khorushak ba bandi tib: nuqotiyoti muhim','Обори арзон бо системаи нӯрӣ нахӯни, бо сабаби кам кардани истифодаи об ва зиёд шудани бартарӣ, усули идеалӣ ҳисоб мешавад. Дар ин мақола мо дар бораи тафсилоти техникӣ ва нуқтаҳои калидии парвариши арзон бо ин система сухан мегӯем.','publish','closed','closed','nigohubonii-zirai-baxtashu-khorushak-ba-bandi-tib',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
